<?php $d=$formData;$reversing=$kind==='reverse'; ?>
<section class="page-heading inventory-heading"><div><h1><?= e($title) ?></h1><p><?= $reversing?'Post a linked reversal; the original entry remains unchanged.':'Change stock for an existing SKU. Every change is recorded in the ledger.' ?></p></div><?php if(can(current_user(),'inventory.view')): ?><a class="button" href="<?= e(url('/inventory')) ?>">Inventory</a><?php endif; ?></section>
<?php if($notice): ?><div class="notice" role="status"><?= e($notice) ?></div><?php endif; ?><?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<form method="post" action="<?= e(url('/inventory/post')) ?>" id="inventory-operation" class="surface inventory-operation"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="kind" value="<?= e($kind) ?>"><input type="hidden" name="request_key" value="<?= e($key) ?>"><input type="hidden" name="product_id" value="<?= (int)($product['id']??0) ?>"><input type="hidden" name="expected_quantity" value="<?= e((string)($product['quantity']??'0.000000')) ?>"><input type="hidden" name="confirmed" value="0"><?php if($original): ?><input type="hidden" name="movement_id" value="<?= (int)$original['id'] ?>"><?php endif; ?>
<div class="product-fields"><label class="wide">Product search *<input type="search" id="inventory-product-search" placeholder="Type at least 2 characters: name, SKU, OEM, brand or bike" autocomplete="off" <?= $reversing?'disabled':'' ?>><span class="subtle-text" id="inventory-search-status" role="status"></span><span id="inventory-search-results"></span></label><div class="inventory-selected wide" id="inventory-selected"><?= $product?e($product['name'].' · '.$product['sku'].' · '.$product['category_name'].($product['subcategory_name']?' / '.$product['subcategory_name']:'')):'Choose an existing product above.' ?></div><label>Current available stock<input id="inventory-current" readonly value="<?= $product?($product['quantity']===null?'Not tracked':e(quantity($product['quantity']))):'—' ?>"></label>
<?php if($kind==='adjust'): ?><label>Physically counted quantity *<input type="number" name="physical_quantity" min="0" step="0.000001" required value="<?= e($d['physical_quantity']??'') ?>"></label><p class="inventory-difference wide" id="inventory-difference" aria-live="polite">Select a product and enter the count to preview the difference.</p><?php elseif(!$reversing): ?><label>Quantity to <?= $kind==='in'?'add':'remove' ?> *<input type="number" name="quantity" min="0.000001" step="0.000001" required value="<?= e($d['quantity']??'') ?>"></label><?php else: ?><div class="info-strip wide">Original #<?= (int)($original['id']??0) ?>: <?= $original?e(App\Services\StockService::label($original)).' · '.e(quantity($original['quantity_delta'])):'Select a valid movement from history.' ?><br>Reversal quantity: <?= $original?e(quantity(bcsub('0',$original['quantity_delta'],6))):'—' ?></div><?php endif; ?>
<?php if($kind==='in'): ?><label>Purchase cost per item (optional)<input type="number" name="unit_cost" min="0" step="0.000001" value="<?= e($d['unit_cost']??'') ?>"><span class="subtle-text">Blank uses current average cost; enter 0 only if free.</span></label><?php endif; ?><label>Entry date *<input type="date" name="entry_date" required value="<?= e($d['entry_date']??'') ?>"></label><label>Reason *<input name="reason" maxlength="150" required list="inventory-reasons" value="<?= e($d['reason']??'') ?>"></label><datalist id="inventory-reasons"><?php foreach(['Damaged goods','Internal use','Missing stock','Supplier return','Stock receipt','Physical count correction','Other'] as $reason): ?><option value="<?= e($reason) ?>"><?php endforeach; ?></datalist><label>Reference number<input name="reference" maxlength="100" value="<?= e($d['reference']??'') ?>"></label><label class="wide">Notes<textarea name="notes" rows="3" maxlength="500"><?= e($d['notes']??'') ?></textarea></label></div><div id="inventory-operation-error" role="alert"></div><footer><button class="button button-primary" type="submit">Review &amp; confirm</button><span role="status" id="inventory-post-status"></span></footer></form>
<dialog id="inventory-confirm-dialog" aria-labelledby="inventory-confirm-title"><h2 id="inventory-confirm-title">Confirm <?= e($title) ?></h2><p id="inventory-confirm-summary"></p><p class="subtle-text">Stock is checked again when posting. Cancelling makes no changes.</p><footer><button class="button" type="button" data-inventory-cancel>Cancel</button><button class="button button-primary" type="button" data-inventory-confirm>Confirm &amp; post</button></footer></dialog>
